func TestSearch_LikeEscapesWildcards(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id":"under","note":"xa_y"}`),
		json.RawMessage(`{"id":"other","note":"xaby"}`),
	}
	if stored, failed, err := s.UpsertBatch("notes", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	} else if failed != 0 || stored != len(items) {
		t.Fatalf("UpsertBatch stored=%d failed=%d, want stored=%d failed=0", stored, failed, len(items))
	}

	results, err := s.Search("a_", 10)
	if err != nil {
		t.Fatalf("Search(a_): %v", err)
	}
	if len(results) != 1 || !strings.Contains(string(results[0]), `"under"`) {
		t.Fatalf("Search(a_) = %q, want only the underscore row", results)
	}
}

func TestFTSMatchQuerySanitizesPunctuation(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	tests := []struct {
		name  string
		input string
		want  string
	}{
		{
			name:  "comma and parens",
			input: `Well drilling, Phase 2 (residential)`,
			want:  `"Well" "drilling" "Phase" "2" "residential"`,
		},
		{
			name:  "embedded quote",
			input: `Alpha "quoted" beta`,
			want:  `"Alpha" "quoted" "beta"`,
		},
		{
			name:  "leading hyphen",
			input: `-Draft- proposal`,
			want:  `"Draft" "proposal"`,
		},
		{
			name:  "bare operators",
			input: `AND OR NOT`,
			want:  `"AND" "OR" "NOT"`,
		},
		{
			name:  "punctuation only",
			input: `!!! , -- () ""`,
			want:  "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			matchQuery := FTSMatchQuery(tt.input)
			if matchQuery != tt.want {
				t.Fatalf("FTSMatchQuery(%q) = %q, want %q", tt.input, matchQuery, tt.want)
			}
			if matchQuery == "" {
				return
			}
			rows, err := s.DB().Query(`SELECT rowid FROM resources_fts WHERE resources_fts MATCH ? LIMIT 1`, matchQuery)
			if err != nil {
				t.Fatalf("FTS MATCH rejected sanitized query %q from %q: %v", matchQuery, tt.input, err)
			}
			if err := rows.Close(); err != nil {
				t.Fatalf("close rows: %v", err)
			}
		})
	}
}

// TestUpsertBatch_PopulatesDeviceTable verifies that UpsertBatch
// dispatches paginated items into both the generic resources table AND the
// typed device table. Regression for issue #268: before the fix, paginated
// syncs only filled the generic resources table, so domain commands that
// query the typed table saw zero rows.
func TestUpsertBatch_PopulatesDeviceTable(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	s, err := Open(dbPath)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
	defer s.Close()

	items := []json.RawMessage{
		json.RawMessage(`{"id": "test-001"}`),
		json.RawMessage(`{"id": "test-002"}`),
		json.RawMessage(`{"id": "test-003"}`),
	}
	if _, _, err := s.UpsertBatch("device", items); err != nil {
		t.Fatalf("UpsertBatch: %v", err)
	}

	db := s.DB()

	var generic int
	if err := db.QueryRow(`SELECT COUNT(*) FROM resources WHERE resource_type = ?`, "device").Scan(&generic); err != nil {
		t.Fatalf("count resources: %v", err)
	}
	if generic != len(items) {
		t.Fatalf("resources count = %d, want %d", generic, len(items))
	}

	var typed int
	typedQuery := fmt.Sprintf(`SELECT COUNT(*) FROM "%s"`, "device")
	if err := db.QueryRow(typedQuery).Scan(&typed); err != nil {
		t.Fatalf("count device: %v", err)
	}
	if typed != len(items) {
		t.Fatalf("device count = %d, want %d (typed table not populated by UpsertBatch)", typed, len(items))
	}
}

